-- Patch for already-seeded environments only.
--
-- Syncs the Vaccination Details section's section_ui_schema to the canonical
-- definition in g2p_register_sections.sql (line
-- 'livestock_vaccination_details_section_01'). The seed only INSERTs and never
-- touches an existing row, so environments seeded before that line changed
-- keep the old dialog forever; this re-applies the whole schema by section_id.
--
-- Why: the official staff-ui cannot fill a dialog column from another
-- section's rows ("sibling-table" source) nor cascade one dialog column from
-- another, so the Ear Tag picker rendered EMPTY (and, on Vaccination, the
-- Vaccine list too). Ear Tag is now a text input (server-checked against this
-- submission's animals), Vaccine the plain VACCINE_TYPE list (server-checked
-- against the animal's species), Species is filled by the server from the
-- animal, and dialog conditions use operators the official UI supports.
-- Generated from the seed line; keep the two in sync.
UPDATE "public"."g2p_register_sections"
SET section_ui_schema = '{"panels": [{"panels": [{"widgets": [{"widget": "dialog-table", "widget-id": "ls_vaccination_details_table", "widget-type": "dialog-table", "widget-label": "Vaccination Details", "widget-readonly": false, "widget-data-path": "51c1f6d6-856a-5e2f-84e9-ff5abdc4fb75.records", "widget-data-columns": [{"widget": "text", "column-key": "ear_tag_id", "widget-type": "input", "widget-label": "Ear Tag / Secondary Identifier", "widget-autofill": {"fields": {"age": "age", "species": "species"}, "matchField": "ear_tag_id", "sourceWidgetId": "ls_animal_details_table"}, "widget-readonly": false, "widget-required": false, "widget-data-path": "ear_tag_id", "widget-placeholder": "ET + 10 digits, e.g. ET0000000123", "widget-data-options": {"actions": [{"action": "require", "condition": {"field": "ear_tag_id", "operator": "empty"}}]}}, {"widget": "select", "column-key": "species", "widget-type": "input", "widget-label": "Species", "widget-readonly": true, "widget-data-path": "species", "widget-data-source": {"type": "api", "method": "POST", "params": {"page_size": 500, "attribute_id": "LIVESTOCK_TYPE"}, "service": "attributes", "endpoint": "values", "labelKey": "value_display", "valueKey": "value_id"}}, {"widget": "text", "column-key": "age", "widget-type": "input", "widget-label": "Age", "widget-readonly": true, "widget-data-path": "age"}, {"widget": "select", "column-key": "vaccine_type", "widget-type": "input", "widget-label": "Vaccine", "widget-readonly": false, "widget-required": false, "widget-data-path": "vaccine_type", "widget-data-source": {"type": "api", "method": "POST", "params": {"page_size": 500, "attribute_id": "VACCINE_TYPE"}, "service": "attributes", "endpoint": "values", "labelKey": "value_display", "valueKey": "value_id"}, "widget-data-options": {"actions": [{"action": "require", "condition": {"field": "vaccine_type", "operator": "empty"}}]}}, {"widget": "date", "column-key": "vaccination_date", "widget-type": "input", "widget-label": "Vaccination Date", "widget-readonly": false, "widget-required": false, "widget-data-path": "vaccination_date", "widget-data-format": {"dateFormat": "DD/MM/YYYY", "inputMethod": "picker", "dateConstraint": "any"}, "widget-data-default": "today", "widget-data-placeholder": "dd_mm_yyyy", "widget-data-options": {"actions": [{"action": "require", "condition": {"field": "vaccination_date", "operator": "empty"}}]}}, {"widget": "date", "column-key": "next_due_date", "widget-type": "input", "widget-label": "Next Due Date", "widget-readonly": false, "widget-data-path": "next_due_date", "widget-data-format": {"dateFormat": "DD/MM/YYYY", "inputMethod": "picker"}, "widget-date-offset": {"daysKey": "interval_days", "baseField": "vaccination_date", "optionsField": "vaccine_type"}, "widget-data-placeholder": "dd_mm_yyyy"}, {"widget": "text", "column-key": "batch_number", "widget-type": "input", "widget-label": "Batch / Lot Number", "widget-readonly": false, "widget-data-path": "batch_number"}, {"widget": "text", "column-key": "administered_by", "widget-type": "input", "widget-label": "Administered By", "widget-readonly": false, "widget-data-path": "administered_by"}, {"widget": "text", "column-key": "notes", "widget-type": "input", "widget-label": "Notes", "widget-readonly": false, "widget-data-path": "notes"}], "widget-data-operations": {"add": true, "edit": true, "remove": true}, "widget-data-dialog-title-add": "Add Vaccination Details", "widget-data-dialog-title-edit": "Edit Vaccination Details"}], "panel-id": "vertical_panel_ls_vaccination_details_1", "panel-orientation": "vertical"}], "panel-id": "horizontal_panel_ls_vaccination_details", "panel-orientation": "horizontal"}], "section-id": "livestock_vaccination_details_section_01", "section-title": "Vaccination Details", "section-editable": true, "section-required-for-submit": false}'::jsonb
WHERE section_id = 'livestock_vaccination_details_section_01';
